// LINE Messaging-API chat ids: groups C + 32 hex, rooms R + 32 hex. A user id
// (U + 32 hex) must NEVER be accepted here — it would be written to
// tasks.group_line_id and used as a push destination (migration 043 header).
const LINE_CHAT_ID = /^[CR][0-9a-f]{32}$/;

const createTaskSchema = z
  .object({
    scope: z.enum(['group', 'personal']).default('group'),
    groupId: z.string().regex(LINE_CHAT_ID, 'invalid LINE chat id').optional(),
    // ...unchanged
  })

export function notifyTarget(task: Pick<TaskRecord, 'is_personal' | 'owner_line_uid' | 'group_line_id'>): string | null {
  if (task.is_personal) return task.owner_line_uid;
  // Defence in depth: never push to a destination that is not a chat id, even
  // if a malformed row reached the table.
  const gid = task.group_line_id;
  return gid && /^[CR][0-9a-f]{32}$/.test(gid) ? gid : null;
}

-- Departure marker. Rows are still never deleted (a former member must stay
-- displayable as the assignee of outstanding tasks), but a stamped row no
-- longer grants access.
ALTER TABLE group_members ADD COLUMN left_at TIMESTAMPTZ;
CREATE INDEX idx_group_members_active
  ON group_members(group_line_id, line_uid) WHERE left_at IS NULL;

export async function isGroupMember(
  supabase: SupabaseClient,
  groupLineId: string,
  lineUid: string,
): Promise<boolean> {
  const { data, error } = await supabase
    .from('group_members')
    .select('id')
    .eq('group_line_id', groupLineId)
    .eq('line_uid', lineUid)
    .is('left_at', null)
    .maybeSingle();
  if (error) throw error;
  return data !== null;
}

export async function ensureGroupMember(
  supabase: SupabaseClient,
  groupLineId: string,
  lineUid: string,
): Promise<boolean> {
  if (await isGroupMember(supabase, groupLineId, lineUid)) return true;
  // Enrolment (including re-enrolment after a left_at stamp) now requires LINE
  // to confirm CURRENT membership. A null here means 'not a member OR LINE was
  // unreachable' — both correctly deny enrolment without locking out anyone who
  // is already on the roster, since that case returned above.
  const profile = await getChatMemberProfileStrict(groupLineId, lineUid);
  if (!profile) return false;
  await upsertGroupMember(supabase, groupLineId, lineUid, profile.displayName, profile.pictureUrl ?? null);
  return true;
}

// inside handleEvent, alongside the memberJoined branch
if (event.type === 'memberLeft') {
  const groupId = event.source.groupId ?? event.source.roomId;
  const leaving = event.left?.members ?? [];
  if (groupId) {
    for (const m of leaving) {
      void supabaseUpdateLeftAt(app, groupId, m.userId);
    }
  }
  return;
}
